def debug(self, method='', scalar=None, value=None):
        ''' Simple debug output. '''

        if self.DEBUG:
            if scalar is None:
                print(':: {}()'.format(method))
            else:
                print('{}() {} {} {}'.format(method, scalar,
                                             type(value).__name__, value))

